-- Food Production ERP 350 Table MySQL Blueprint
CREATE DATABASE IF NOT EXISTS food_production_erp;
USE food_production_erp;

CREATE TABLE IF NOT EXISTS `company` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `code` VARCHAR(50) NULL,
  `name` VARCHAR(180) NULL,
  `branch_id` BIGINT UNSIGNED NULL,
  `warehouse_id` BIGINT UNSIGNED NULL,
  `batch_no` VARCHAR(80) NULL,
  `expiry_date` DATE NULL,
  `qty` DECIMAL(18,4) DEFAULT 0,
  `rate` DECIMAL(18,4) DEFAULT 0,
  `amount` DECIMAL(18,4) DEFAULT 0,
  `status` VARCHAR(40) DEFAULT 'active',
  `description` TEXT NULL,
  `created_by` BIGINT UNSIGNED NULL,
  `updated_by` BIGINT UNSIGNED NULL,
  `created_at` TIMESTAMP NULL,
  `updated_at` TIMESTAMP NULL,
  PRIMARY KEY (`id`),
  KEY `idx_company_code` (`code`),
  KEY `idx_company_branch` (`branch_id`),
  KEY `idx_company_batch` (`batch_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

